const entrada = $input.first()?.json ?? {};

const system = typeof entrada.MSG_Prompt_System === 'string'
  ? entrada.MSG_Prompt_System.trim()
  : '';

const user = typeof entrada.MSG_Prompt_User === 'string'
  ? entrada.MSG_Prompt_User.trim()
  : '';

if (!system || !user) {
  throw new Error(
    'CORE Cloudflare: MSG_Prompt_System e MSG_Prompt_User são obrigatórios.'
  );
}

return [
  {
    json: {
      _route: 'request',
      contexto: {
        modelo: '@cf/meta/llama-3.3-70b-instruct-fp8-fast',

        request_body: {
          messages: [
            {
              role: 'system',
              content: system
            },
            {
              role: 'user',
              content: user
            }
          ],
          max_tokens: 1024,
          stream: false
        },

        _core: {
          tentativa: 1,
          max_tentativas: 3
        }
      }
    }
  }
];

let context = $('Validar e Preparar').first().json.contexto;
try { const retry = $('Incrementar Tentativa').last().json.contexto; if (retry) context = retry; } catch {}
const response = $json ?? {};
const status = Number(response.statusCode ?? 0);
const body = response.body ?? response;
const result = body?.result;
const text = typeof result?.response === 'string' ? result.response.trim() : '';
if (status >= 200 && status < 300 && body?.success !== false && text) {
  return [{ json: { _route: 'success', contexto: context, text, usage: result?.usage ?? null } }];
}
const transient = !status || [408, 425, 500, 502, 503, 504].includes(status);
const attempt = Number(context._core.tentativa);
const retry = transient && attempt < Number(context._core.max_tentativas);
const code = status === 429 ? 'LIMIT_EXCEEDED' : [401, 403].includes(status) ? 'AUTHENTICATION_FAILED' : status === 404 ? 'MODEL_UNAVAILABLE' : status >= 200 && status < 300 ? 'INVALID_RESPONSE' : transient ? 'COMMUNICATION_ERROR' : 'API_ERROR';
return [{ json: { _route: retry ? 'retry' : 'error', contexto: context, code, status_code: status || null, retry_delay_seconds: retry ? Math.min(2 ** attempt, 10) : null } }];

const item = $input.first().json;
const context = item.contexto;
return [{ json: {
  _route: 'request',
  contexto: {
    ...context,
    _core: { ...context._core, tentativa: Number(context._core.tentativa) + 1 }
  }
}}];

// Localiza o registro retornado pela procedure, inclusive quando o
// resultado do MySQL vem como arrays ou objetos aninhados.
function encontrarRegistro(valor, profundidade = 0) {
  if (profundidade > 6 || valor == null || typeof valor !== 'object') {
    return null;
  }

  if (!Array.isArray(valor) && 'dsc_api_key' in valor) {
    return valor;
  }

  for (const item of Object.values(valor)) {
    const registro = encontrarRegistro(item, profundidade + 1);
    if (registro) return registro;
  }

  return null;
}

const itensSP = $input.all();
const api = encontrarRegistro(itensSP.map(item => item.json));

if (!api || api.id == null) {
  throw new Error('CORE Cloudflare: nenhuma conta disponível na SP.');
}

// Neste cadastro, confirmar que:
// dsc_api_key    = Account ID
// dsc_api_secret = API Token
const accountId = String(api.dsc_api_key ?? '').trim();
const apiToken = String(api.dsc_api_secret ?? '').trim();

if (!/^[a-f0-9]{32}$/i.test(accountId)) {
  throw new Error(
    'CORE Cloudflare: Account ID ausente ou inválido no campo dsc_api_key.'
  );
}

if (!apiToken) {
  throw new Error(
    'CORE Cloudflare: API Token ausente no campo dsc_api_secret.'
  );
}

// Preserva a tentativa atual quando a execução retorna pelo retry.
let contexto = $('Validar e Preparar').first().json.contexto;

try {
  const retry = $('Incrementar Tentativa').last().json.contexto;
  if (retry) contexto = retry;
} catch {
  // Primeira tentativa: o node de retry ainda não foi executado.
}

return [
  {
    json: {
      _route: 'request',
      contexto: {
        ...contexto,
        account_id: accountId,
        api_id: api.id,
        api_token: apiToken
      }
    }
  }
];
